EXPORT ZZT_ENCCPLX() BEGIN
LOCAL R,O:={}; HComplex:=1; M1:=[[(1,1),4],[3,(8,-1)]];
IFERR R:=stddev([[(0.5,-3),(-1,3)]],[[0+3.25],[2]]); IF TYPE(R)==0 OR TYPE(R)==3 THEN O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),8),ROUND(IM(R),8)}}); ELSE O:=CONCAT(O,{{TYPE(R),STRING(R)}}); END; THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[(0.5,-3)],[(-1,3)]],[[0+3.25,2]]); IF TYPE(R)==0 OR TYPE(R)==3 THEN O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),8),ROUND(IM(R),8)}}); ELSE O:=CONCAT(O,{{TYPE(R),STRING(R)}}); END; THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[(4.5,1),(0,-3),(6,3)]],[[0+3.25],[-1],[-1]]); IF TYPE(R)==0 OR TYPE(R)==3 THEN O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),8),ROUND(IM(R),8)}}); ELSE O:=CONCAT(O,{{TYPE(R),STRING(R)}}); END; THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[(4.5,1)],[(0,-3)],[(6,3)]],[[0+3.25,-1,-1]]); IF TYPE(R)==0 OR TYPE(R)==3 THEN O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),8),ROUND(IM(R),8)}}); ELSE O:=CONCAT(O,{{TYPE(R),STRING(R)}}); END; THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[(7.5,2),(5,-3),(-4,-1),(2,-2)]],[[-0.75,4],[5,3]]); IF TYPE(R)==0 OR TYPE(R)==3 THEN O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),8),ROUND(IM(R),8)}}); ELSE O:=CONCAT(O,{{TYPE(R),STRING(R)}}); END; THEN O:=CONCAT(O,{"caught"}); END;
IFERR R:=stddev([[(7.5,2),(5,-3)],[(-4,-1),(2,-2)]],[[-0.75,4,5,3]]); IF TYPE(R)==0 OR TYPE(R)==3 THEN O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),8),ROUND(IM(R),8)}}); ELSE O:=CONCAT(O,{{TYPE(R),STRING(R)}}); END; THEN O:=CONCAT(O,{"caught"}); END;
RETURN O; END;
